import cats.*, cats.implicits.*

val sum: Int    = List(1, 2, 3).combineAll          // Monoid[Int]
val anyM: Boolean = List(true, false).combineAllOrEmpty  // Monoid[Boolean] is disjunction

// a Monoid on a domain type
case class Money(cents: Long)
object Money {
  given Monoid[Money] = Monoid(Money(0), (a, b) => Money(a.cents + b.cents))
}

